"""Schema for the disposable operator application read model."""
from __future__ import annotations
import sqlite3

SCHEMA_VERSION = 1

def create_schema(connection: sqlite3.Connection, *, release_commit_sha: str, implementation_digest: str) -> None:
    connection.executescript("""
    CREATE TABLE IF NOT EXISTS schema_metadata (singleton_id INTEGER PRIMARY KEY CHECK(singleton_id=1), schema_version INTEGER NOT NULL, created_at TEXT NOT NULL, release_commit_sha TEXT NOT NULL, implementation_digest TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS import_batches (import_batch_id TEXT PRIMARY KEY, imported_at TEXT NOT NULL, source_release_commit_sha TEXT NOT NULL, source_implementation_digest TEXT NOT NULL, source_count INTEGER NOT NULL, accepted_count INTEGER NOT NULL, rejected_count INTEGER NOT NULL, batch_digest TEXT NOT NULL UNIQUE);
    CREATE TABLE IF NOT EXISTS operator_snapshots (snapshot_id TEXT PRIMARY KEY, generated_as_of TEXT NOT NULL, release_commit_sha TEXT NOT NULL, implementation_digest TEXT NOT NULL, operating_mode TEXT NOT NULL, operational_status TEXT NOT NULL, supervised_readiness_status TEXT NOT NULL, recommended_operator_action TEXT NOT NULL, evidence_completeness TEXT NOT NULL, evidence_freshness TEXT NOT NULL, suspension_status TEXT NOT NULL, heartbeat_status TEXT NOT NULL, alert_status TEXT NOT NULL, acknowledgment_status TEXT NOT NULL, recovery_status TEXT NOT NULL, blocker_reasons_json TEXT NOT NULL, source_component_statuses_json TEXT NOT NULL, strategy_enabled INTEGER NOT NULL CHECK(strategy_enabled=0), activation_approvals_present INTEGER NOT NULL CHECK(activation_approvals_present=0), approved_protection_state_count INTEGER NOT NULL CHECK(approved_protection_state_count=0), protection_grounded INTEGER NOT NULL CHECK(protection_grounded=0), activation_approved INTEGER NOT NULL CHECK(activation_approved=0), permits_automated_action INTEGER NOT NULL CHECK(permits_automated_action=0), live_ready INTEGER NOT NULL CHECK(live_ready=0), unattended_ready INTEGER NOT NULL CHECK(unattended_ready=0), canonical_digest TEXT NOT NULL UNIQUE, import_batch_id TEXT NOT NULL REFERENCES import_batches(import_batch_id));
    CREATE TABLE IF NOT EXISTS operator_events (event_id TEXT PRIMARY KEY, event_type TEXT NOT NULL, severity TEXT NOT NULL, occurred_at TEXT NOT NULL, source_snapshot_id TEXT REFERENCES operator_snapshots(snapshot_id), source_component TEXT NOT NULL, headline TEXT NOT NULL, detail_code TEXT NOT NULL, operational_status TEXT NOT NULL, supervised_readiness_status TEXT NOT NULL, blocker_reasons_json TEXT NOT NULL, operator_action TEXT NOT NULL, permits_automated_action INTEGER NOT NULL CHECK(permits_automated_action=0), live_ready INTEGER NOT NULL CHECK(live_ready=0), unattended_ready INTEGER NOT NULL CHECK(unattended_ready=0), canonical_digest TEXT NOT NULL UNIQUE, import_batch_id TEXT NOT NULL REFERENCES import_batches(import_batch_id));
    CREATE TABLE IF NOT EXISTS operator_incidents (incident_id TEXT PRIMARY KEY, source_event_id TEXT NOT NULL REFERENCES operator_events(event_id), incident_type TEXT NOT NULL, severity TEXT NOT NULL, opened_at TEXT NOT NULL, latest_observed_at TEXT NOT NULL, observation_status TEXT NOT NULL, source_component TEXT NOT NULL, headline TEXT NOT NULL, detail_code TEXT NOT NULL, blocker_reasons_json TEXT NOT NULL, recommended_operator_action TEXT NOT NULL, operational_status TEXT NOT NULL, supervised_readiness_status TEXT NOT NULL, evidence_completeness TEXT NOT NULL, evidence_freshness TEXT NOT NULL, strategy_enabled INTEGER NOT NULL CHECK(strategy_enabled=0), activation_approvals_present INTEGER NOT NULL CHECK(activation_approvals_present=0), protection_grounded INTEGER NOT NULL CHECK(protection_grounded=0), activation_approved INTEGER NOT NULL CHECK(activation_approved=0), permits_automated_action INTEGER NOT NULL CHECK(permits_automated_action=0), live_ready INTEGER NOT NULL CHECK(live_ready=0), unattended_ready INTEGER NOT NULL CHECK(unattended_ready=0), canonical_digest TEXT NOT NULL UNIQUE, import_batch_id TEXT NOT NULL REFERENCES import_batches(import_batch_id));
    CREATE TABLE IF NOT EXISTS incident_evidence_links (incident_id TEXT NOT NULL REFERENCES operator_incidents(incident_id) ON DELETE CASCADE, evidence_type TEXT NOT NULL, evidence_id TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), PRIMARY KEY(incident_id,evidence_type,evidence_id), UNIQUE(incident_id,ordinal));
    CREATE INDEX IF NOT EXISTS snapshots_as_of ON operator_snapshots(generated_as_of DESC); CREATE INDEX IF NOT EXISTS snapshots_status ON operator_snapshots(operational_status); CREATE INDEX IF NOT EXISTS snapshots_readiness ON operator_snapshots(supervised_readiness_status);
    CREATE INDEX IF NOT EXISTS events_occurred ON operator_events(occurred_at DESC); CREATE INDEX IF NOT EXISTS events_type ON operator_events(event_type); CREATE INDEX IF NOT EXISTS events_severity ON operator_events(severity); CREATE INDEX IF NOT EXISTS events_snapshot ON operator_events(source_snapshot_id);
    CREATE INDEX IF NOT EXISTS incidents_observed ON operator_incidents(latest_observed_at DESC); CREATE INDEX IF NOT EXISTS incidents_type ON operator_incidents(incident_type); CREATE INDEX IF NOT EXISTS incidents_status ON operator_incidents(observation_status); CREATE INDEX IF NOT EXISTS incidents_severity ON operator_incidents(severity);
    """)
    connection.execute("INSERT INTO schema_metadata VALUES (1, ?, datetime('now'), ?, ?)", (SCHEMA_VERSION, release_commit_sha, implementation_digest))
